#!/usr/bin/env python3
"""Frozen exact state-index ledger for the 3,874-cell generic-H6 endpoint.

Generated from the exact face-(2,3) saturation/reflection closure result.
The bit at position i is 1 iff state index i in the canonical 14,174-state H6
universe survives. The canonical sorted-index serialization has SHA-256
b5e05331a267ea5c764b96ef834c1a6ffd5f03599b372e86cae3b8e77ea9666a.
"""
import hashlib

UNIVERSE_SIZE = 14174
ENDPOINT_SIZE = 3874
INDEX_SHA256 = "b5e05331a267ea5c764b96ef834c1a6ffd5f03599b372e86cae3b8e77ea9666a"
ENDPOINT_HEX = ""


def decode_endpoint():
    bits = int(ENDPOINT_HEX, 16)
    out = tuple(i for i in range(UNIVERSE_SIZE) if (bits >> i) & 1)
    assert len(out) == ENDPOINT_SIZE
    raw = (",".join(map(str, out)) + "\n").encode()
    assert hashlib.sha256(raw).hexdigest() == INDEX_SHA256
    return out


if __name__ == "__main__":
    out = decode_endpoint()
    print("PASS")
    print("size", len(out))
    print("sha256", INDEX_SHA256)
